mapper.select:
select distinct m.* from music m where m.is_deleted = 0
and ( m.music_name like concat('%', #{keyword}, '%') or m.type_id in ( select c.id from category c where c.is_deleted = 0 and c.type_name like concat('%', #{keyword}, '%') union select c2.id from category c2 where c2.is_deleted = 0 and c2.parent_id in (select c3.id from category c3 where c3.is_deleted = 0 and c3.type_name like concat('%', #{keyword}, '%')) union select c4.id from category c4 where c4.is_deleted = 0 and c4.id in (select c5.parent_id from category c5 where c5.is_deleted = 0 and c5.type_name like concat('%', #{keyword}, '%') and c5.parent_id != 0) ) or m.id in ( select distinct r.music_id from music_tag_relation r join tag t on r.tag_id = t.id where r.is_deleted = 0 and t.is_deleted = 0 and t.tag_name like concat('%', #{keyword}, '%') ) )
order by m.id limit #{offSet}, #{pageSize}

